messages.content:
Tool response:
Tool: create_corrective_service_ticket
Description: Create Corrective Service Ticket
Parameters:
    {
      "type": "object",
      "properties": {
        "equipment_asset_tag": {
          "type": "string",
          "title": "Equipment Asset Tag",
          "description": "Asset tag of the equipment requiring service"
        },
        "location_name": {
          "type": "string",
          "title": "Location Name",
          "description": "Name of the location where the equipment is currently situated"
        },
        "priority": {
          "type": "string",
          "title": "Priority",
          "description": "Priority level of the service ticket (Low, Medium, High, Critical)"
        },
        "issue_description": {
          "type": "string",
          "title": "Issue Description",
          "description": "Detailed description of the issue encountered with the equipment"
        },
        "assigned_engineer_full_name": {
          "type": "string",
          "title": "Assigned Engineer Full Name",
          "description": "Full name of the biomedical engineer to whom the ticket should be assigned"
        },
        "expected_resolution_date": {
          "type": "string",
          "title": "Expected Resolution Date",
          "description": "Expected date by which the issue should be resolved (YYYY-MM-DD format)"
        }
      },
      "required": [
        "equipment_asset_tag",
        "location_name",
        "priority",
        "issue_description",
        "assigned_engineer_full_name",
        "expected_resolution_date"
      ]
    }
